#include "Internal.hxx"
#include <STEPControl_Reader.hxx>
#include <StepData_StepModel.hxx>
#include <IFSelect_ReturnStatus.hxx>
#include <Standard_Failure.hxx>
#include <filesystem>
namespace DrawVerify::Occt { namespace { std::string unitName(const double scale){if(std::abs(scale-1.)<1e-12)return "millimeter";if(std::abs(scale-25.4)<1e-12)return "inch";if(std::abs(scale-1000.)<1e-12)return "meter";if(std::abs(scale-10.)<1e-12)return "centimeter";if(std::abs(scale-.001)<1e-12)return "micron";return "custom";} } StepReader::StepReader()=default; OperationResult StepReader::LoadStep(const std::string&p){result_={};roots_=transferred_=0;model_=Model(); if(p.empty()){return result_={ErrorCode::InvalidArgument,"STEP path is empty",{{ErrorCode::InvalidArgument,"LoadStep","STEP path is empty"}}};} if(!std::filesystem::exists(p)){return result_={ErrorCode::FileNotFound,"STEP file was not found",{{ErrorCode::FileNotFound,"LoadStep",p}}};} auto ext=std::filesystem::path(p).extension().string(); for(auto& c:ext)c=static_cast<char>(tolower(c)); if(ext!=".step"&&ext!=".stp")return result_={ErrorCode::UnsupportedFile,"Only .step and .stp are supported",{{ErrorCode::UnsupportedFile,"LoadStep",p}}}; try{ STEPControl_Reader reader; if(reader.ReadFile(p.c_str())!=IFSelect_RetDone)return result_={ErrorCode::StepReadFailed,"OCCT could not read the STEP file",{{ErrorCode::StepReadFailed,"ReadFile",p}}}; roots_=reader.NbRootsForTransfer(); transferred_=reader.TransferRoots(); auto shape=reader.OneShape(); if(shape.IsNull())return result_={ErrorCode::EmptyModel,"STEP transfer produced an empty shape",{{ErrorCode::EmptyModel,"TransferRoots",p}}}; auto impl=std::make_shared<Model::Impl>();impl->shape=shape; const auto stepModel=reader.StepModel(); if(!stepModel.IsNull()&&stepModel->IsInitializedUnit()){impl->millimeters=stepModel->LocalLengthUnit();impl->unit=unitName(impl->millimeters);} model_=Model(impl); return result_={ErrorCode::Success,"STEP loaded",{}};}catch(const Standard_Failure& e){return result_={ErrorCode::OcctFailure,e.what(),{{ErrorCode::OcctFailure,"LoadStep",e.what()}}};}catch(const std::exception&e){return result_={ErrorCode::NativeFailure,e.what(),{{ErrorCode::NativeFailure,"LoadStep",e.what()}}};}} Model StepReader::GetModel()const{return model_;} int StepReader::GetRootCount()const{return roots_;}int StepReader::GetTransferredRootCount()const{return transferred_;}OperationResult StepReader::GetTransferStatus()const{return result_;}std::vector<Diagnostic> StepReader::GetTransferDiagnostics()const{return result_.diagnostics;} }
